import app.repositories.SqlKindRepository;
import app.repositories.SqlOrderRepository;
import app.repositories.SqlThingRepository;
import app.repositories.ThingRepository;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.function.Function;

/** The repositories over one JDBC connection, and its transaction. */
public class SqlUnitOfWork implements UnitOfWork {
    private final Connection connection;
    private final ThingRepository things;
    private final KindRepository kinds;
    private final OrderRepository order;
    private final AuditEntryRepository auditEntries;
    private final EmptyRepository empties;

    public SqlUnitOfWork(Connection connection) {
        this.connection = connection;
        this.things = new SqlThingRepository(connection);
        this.kinds = new SqlKindRepository(connection);
        this.order = new SqlOrderRepository(connection);
        this.auditEntries = new SqlAuditEntryRepository(connection);
        this.empties = new SqlEmptyRepository(connection);
    }

    public Connection connection() {
        return connection;
    }

    @Override
    public ThingRepository things() {
        return things;
    }

    @Override
    public KindRepository kinds() {
        return kinds;
    }

    @Override
    public OrderRepository order() {
        return order;
    }

    @Override
    public AuditEntryRepository auditEntries() {
        return auditEntries;
    }

    @Override
    public EmptyRepository empties() {
        return empties;
    }

    @Override
    public <T> T transaction(Function<UnitOfWork, T> work) {
        try {
            // Joins the transaction already open
            if (!connection.getAutoCommit()) return work.apply(this);
            connection.setAutoCommit(false);
            try {
                T result = work.apply(this);
                connection.commit();
                return result;
            } catch (RuntimeException error) {
                connection.rollback();
                throw error;
            } finally {
                connection.setAutoCommit(true);
            }
        } catch (SQLException error) {
            throw Sql.failure(error);
        }
    }
}

