            if (entity.getOrderId() != null) { names.add("`orderId`"); values.add(entity.getOrderId()); }
            if (entity.getMessage() != null) { names.add("`message`"); values.add(entity.getMessage()); }
            String sql = names.isEmpty()
                    ? "INSERT INTO `audit_entries` () VALUES ()"
                    : "INSERT INTO `audit_entries` (" + String.join(", ", names) + ") VALUES (" + String.join(", ", Collections.nCopies(names.size(), "?")) + ")";
            Long id = Sql.insert(connection, sql, values.toArray());
