            throw new ConflictException("AuditEntry", "the database refused the change: " + error.getMessage());
        }
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM `audit_entries` WHERE `entry_no` = ?", (row) -> fill(row, entity), entity.getEntryNo())
                .orElseThrow(() -> new IllegalStateException("The AuditEntry just written is not there"));
    }

    @Override
    public AuditEntry update(AuditEntry entity) {
        try {
            Sql.run(connection, "UPDATE `audit_entries` SET `orderId` = ?, `message` = ? WHERE `entry_no` = ?", entity.getOrderId(), entity.getMessage(), entity.getEntryNo());
        } catch (Sql.RefusedException error) {
            throw new ConflictException("AuditEntry", "the database refused the change: " + error.getMessage());
        }
        return Sql.one(connection, "SELECT " + COLUMNS + " FROM `audit_entries` WHERE `entry_no` = ?", (row) -> fill(row, entity), entity.getEntryNo())
                .orElseThrow(() -> new IllegalStateException("The AuditEntry just written is not there"));
    }

    @Override
    public void delete(AuditEntry entity) {
        try {
            Sql.run(connection, "DELETE FROM `audit_entries` WHERE `entry_no` = ?", entity.getEntryNo());
