/** Operations on audit_entries. Each write runs in its own transaction. */
public class AuditEntryService {
    private final UnitOfWork uow;

    public AuditEntryService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "audit_entries" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, AuditEntry current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("orderId");
            if (value == null) {
                if (creating || values.containsKey("orderId")) errors.add(new FieldError("orderId", "is required"));
            }
        }
        {
            Object value = values.get("message");
            if (value == null) {
                if (creating || values.containsKey("message")) errors.add(new FieldError("message", "is required"));
            } else {
                if (value instanceof String text && text.length() > 200) errors.add(new FieldError("message", "is longer than 200 characters"));
            }
        }
        {
            Long orderId = (Long) (values.containsKey("orderId") ? values.get("orderId") : current == null ? null : current.getOrderId());
            if (orderId != null && uow.order().findById(orderId).isEmpty())
                errors.add(new FieldError("orderId", "no Order has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("AuditEntry", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, AuditEntry current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(AuditEntry entity, Map<String, Object> values) {
        if (values.containsKey("orderId")) entity.setOrderId((Long) values.get("orderId"));
        if (values.containsKey("message")) entity.setMessage((String) values.get("message"));
    }

    /** The AuditEntry with this key; NotFoundException when there is none. */
    private AuditEntry find(UnitOfWork uow, Integer entryNo) {
        return uow.auditEntries().findByEntryNo(entryNo).orElseThrow(() -> new NotFoundException("AuditEntry", entryNo));
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(AuditEntryChanges changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.orderId() != null && changes.orderId().isPresent()) values.put("orderId", changes.orderId().value());
        if (changes.message() != null && changes.message().isPresent()) values.put("message", changes.message().value());
        return values;
    }

    /** Stores a new AuditEntry after checking it. */
    public AuditEntry createAuditEntry(AuditEntry auditEntry) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (auditEntry.getOrderId() != null) values.put("orderId", auditEntry.getOrderId());
        if (auditEntry.getMessage() != null) values.put("message", auditEntry.getMessage());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.auditEntries().insert(auditEntry);
        });
    }

    /** The AuditEntry with this key; NotFoundException when there is none. */
    public AuditEntry getAuditEntry(Integer entryNo) {
        return find(uow, entryNo);
    }

    /** A page of audit_entries, by primary key. */
    public Page<AuditEntry> listAuditEntries(int offset, int limit) {
        return uow.auditEntries().list(offset, limit);
    }

    /** Changes the given values of a AuditEntry. */
    public AuditEntry updateAuditEntry(Integer entryNo, AuditEntryChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            AuditEntry current = find(uow, entryNo);
            check(uow, values, current);
            apply(current, values);
            return uow.auditEntries().update(current);
        });
    }

    /** Deletes a AuditEntry. */
    public void deleteAuditEntry(Integer entryNo) {
        uow.transaction((uow) -> {
            AuditEntry current = find(uow, entryNo);
            uow.auditEntries().delete(current);
            return null;
        });
    }

    /** The audit_entries with this orderId. */
    public List<AuditEntry> listAuditEntriesByOrderId(Long orderId) {
        return uow.auditEntries().listByOrderId(orderId);
    }
}

