        if (changes.r() != null && changes.r().isPresent()) values.put("r", changes.r().value());
        if (changes.d() != null && changes.d().isPresent()) values.put("d", changes.d().value());
        if (changes.flag() != null && changes.flag().isPresent()) values.put("flag", changes.flag().value());
        if (changes.born() != null && changes.born().isPresent()) values.put("born", changes.born().value());
        if (changes.opens() != null && changes.opens().isPresent()) values.put("opens", changes.opens().value());
        if (changes.at() != null && changes.at().isPresent()) values.put("at", changes.at().value());
        if (changes.changed() != null && changes.changed().isPresent()) values.put("changed", changes.changed().value());
        if (changes.bin() != null && changes.bin().isPresent()) values.put("bin", changes.bin().value());
        if (changes.blobby() != null && changes.blobby().isPresent()) values.put("blobby", changes.blobby().value());
        if (changes.data() != null && changes.data().isPresent()) values.put("data", changes.data().value());
        if (changes.feeling() != null && changes.feeling().isPresent()) values.put("feeling", changes.feeling().value());
        if (changes.code() != null && changes.code().isPresent()) values.put("code", changes.code().value());
        if (changes.note() != null && changes.note().isPresent()) values.put("note", changes.note().value());
        if (changes.longNote() != null && changes.longNote().isPresent()) values.put("longNote", changes.longNote().value());
        return values;
    }

    /** Stores a new Thing after checking it. */
    public Thing createThing(Thing thing) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (thing.getId() != null) values.put("id", thing.getId());
        if (thing.getTiny() != null) values.put("tiny", thing.getTiny());
        if (thing.getSmall() != null) values.put("small", thing.getSmall());
        if (thing.getMedium() != null) values.put("medium", thing.getMedium());
        if (thing.getNum() != null) values.put("num", thing.getNum());
        if (thing.getBig() != null) values.put("big", thing.getBig());
        if (thing.getPrice() != null) values.put("price", thing.getPrice());
        if (thing.getR() != null) values.put("r", thing.getR());
        if (thing.getD() != null) values.put("d", thing.getD());
        if (thing.getFlag() != null) values.put("flag", thing.getFlag());
        if (thing.getBorn() != null) values.put("born", thing.getBorn());
        if (thing.getOpens() != null) values.put("opens", thing.getOpens());
        if (thing.getAt() != null) values.put("at", thing.getAt());
        if (thing.getChanged() != null) values.put("changed", thing.getChanged());
        if (thing.getBin() != null) values.put("bin", thing.getBin());
        if (thing.getBlobby() != null) values.put("blobby", thing.getBlobby());
        if (thing.getData() != null) values.put("data", thing.getData());
        if (thing.getFeeling() != null) values.put("feeling", thing.getFeeling());
        if (thing.getCode() != null) values.put("code", thing.getCode());
        if (thing.getNote() != null) values.put("note", thing.getNote());
        if (thing.getLongNote() != null) values.put("longNote", thing.getLongNote());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            return uow.things().insert(thing);
        });
    }

    /** The Thing with this key; NotFoundException when there is none. */
    public Thing getThing(byte[] id) {
        return find(uow, id);
    }

    /** A page of things, by primary key. */
    public Page<Thing> listThings(int offset, int limit) {
        return uow.things().list(offset, limit);
    }

    /** Changes the given values of a Thing. */
    public Thing updateThing(byte[] id, ThingChanges changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Thing current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return uow.things().update(current);
        });
    }

    /** Deletes a Thing. */
    public void deleteThing(byte[] id) {
        uow.transaction((uow) -> {
            Thing current = find(uow, id);
            uow.things().delete(current);
            return null;
        });
    }
}

