package app;

import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.List;

/** The test database: the one TEST_DATABASE_URL names (with TEST_DATABASE_USER and TEST_DATABASE_PASSWORD), created from the schema before every test. */
final class TestDatabase {
    // The tables are written for one kind of database: the tests cannot fall back to SQLite
    static final String URL = System.getenv("TEST_DATABASE_URL");
    static final String USER = System.getenv("TEST_DATABASE_USER");
    static final String PASSWORD = System.getenv("TEST_DATABASE_PASSWORD");

    /** Removes every table, so the database starts empty. */
    static final List<String> DROP = List.of(
            "SET FOREIGN_KEY_CHECKS = 0",
            "DROP TABLE IF EXISTS `empties`",
            "DROP TABLE IF EXISTS `audit_entries`",
            "DROP TABLE IF EXISTS `Order`",
            "DROP TABLE IF EXISTS `kinds`",
            "DROP TABLE IF EXISTS `things`",
            "SET FOREIGN_KEY_CHECKS = 1"
    );

    /** Creates every table, in an order the database accepts. */
    static final List<String> CREATE = List.of(
            "CREATE TABLE `things` (
  `id` binary(16) NOT NULL,
  `tiny` tinyint NOT NULL,
  `small` smallint NOT NULL,
  `medium` mediumint,
  `num` int unsigned,
  `big` bigint NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `r` float NOT NULL,
  `d` double,
  `flag` tinyint(1) NOT NULL DEFAULT TRUE,
  `born` date NOT NULL,
  `opens` time NOT NULL,
  `at` datetime(6) NOT NULL,
  `at_ts` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `changed` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `bin` varbinary(50) NOT NULL,
  `blobby` blob,
  `data` json NOT NULL,
  `feeling` ENUM('sad', 'ok', 'very happy') NOT NULL,
  `code` char(5) NOT NULL,
  `note` text,
  `long_note` longtext,
  `total` decimal(12,2) GENERATED ALWAYS AS (price * 2) STORED,
  PRIMARY KEY (`id`)
)",
            "CREATE TABLE `kinds` (
  `code` varchar(10) NOT NULL,
  `day` date NOT NULL,
  `label` varchar(30),
  PRIMARY KEY (`code`, `day`)
)",
            "CREATE TABLE `Order` (
  `Id` bigint unsigned AUTO_INCREMENT NOT NULL,
  `user` varchar(40) NOT NULL,
  `group` int NOT NULL DEFAULT 0,
  `customerName` varchar(60) NOT NULL,
  `class` text,
  `metadata` text,
  `date` date,
  `time` time,
  `text` varchar(20),
  `list` text,
  `str` varchar(10),
  `int` integer,
  `dueDate` date NOT NULL,
  `closesAt` time,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `kind_code` varchar(10),
  `kind_day` date,
  `thing_id` binary(16),
  `parentId` bigint unsigned,
  PRIMARY KEY (`Id`),
  UNIQUE (`customerName`),
  CHECK (`group` >= 0),
  FOREIGN KEY (`thing_id`) REFERENCES `things` (`id`) ON DELETE SET NULL,
  FOREIGN KEY (`parentId`) REFERENCES `Order` (`Id`),
  FOREIGN KEY (`kind_code`, `kind_day`) REFERENCES `kinds` (`code`, `day`)
)",
            "CREATE TABLE `audit_entries` (
  `entry_no` int AUTO_INCREMENT NOT NULL,
  `orderId` bigint unsigned NOT NULL,
  `message` varchar(200) NOT NULL,
  PRIMARY KEY (`entry_no`),
  FOREIGN KEY (`orderId`) REFERENCES `Order` (`Id`) ON DELETE CASCADE
)",
            "CREATE TABLE `empties` (
  `id` bigint AUTO_INCREMENT NOT NULL,
  `note` text,
  PRIMARY KEY (`id`)
)"
    );

    private TestDatabase() {}

    /** A connection to the test database, with every table dropped and created again; on that one connection, as MySQL turns its foreign key checks off for the connection that asks. */
    static Connection open() throws SQLException {
        if (URL == null)
            throw new IllegalStateException("The database tests need a disposable MySQL database: set TEST_DATABASE_URL (it is emptied)");
        Connection connection = Database.connect(URL, USER, PASSWORD);
        try (Statement statement = connection.createStatement()) {
            for (String sql : DROP) statement.execute(sql);
            for (String sql : CREATE) statement.execute(sql);
        }
        return connection;
    }
}

