/** Tests of the "things" table. */
class ThingTest {
    private Connection connection;
    /** The repositories over the test database, opened empty for every test */
    private SqlUnitOfWork uow;

    @BeforeEach
    void open() throws SQLException {
        connection = TestDatabase.open();
        uow = new SqlUnitOfWork(connection);
    }

    @AfterEach
    void close() throws SQLException {
        if (!connection.getAutoCommit()) connection.rollback();
        connection.close();
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Thing stored = Factories.addThing(uow, 1);
