            var found = service.getThing(created.getId());
            org.junit.jupiter.api.Assertions.assertArrayEquals(created.getId(), found.getId());
        }

        @Test
        void refusesAMissingValue() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            row.setId(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createThing(row));
            assertEquals(List.of("id"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void saysWhenARowIsMissing() {
            ThingService service = new ThingService(uow);
            assertThrows(NotFoundException.class, () -> service.getThing(new byte[] { -1, -1 }));
        }

        @Test
        void changesARow() {
            ThingService service = new ThingService(uow);
            int n = 100;
            Thing row = Factories.newThing(1);
            var created = service.createThing(row);
            var updated = service.updateThing(created.getId(), new ThingChanges(Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.of("changed"), Patch.absent()));
            assertEquals("changed", updated.getNote());
        }

        @Test
